@Test
void restartValidationDetectsSameSizeObjectTamperingFromPersistedChunkDigests() throws Exception {
    var limits = new ArtifactLimits(8, 4, 32, 100, 80, Duration.ofHours(24), Duration.ofDays(7));
    byte[] payload = "abcdefgh".getBytes(StandardCharsets.UTF_8);
    var first = store(limits);
    var upload = first.beginUpload(new ResumableUpload(
            SCOPE, "text/plain", "persisted.txt", payload.length, Hashing.sha256Hex(payload)), NOW);
    first.putChunk(upload.uploadId(), new UploadChunk(0, "abcd".getBytes(StandardCharsets.UTF_8)), NOW);
    first.putChunk(upload.uploadId(), new UploadChunk(1, "efgh".getBytes(StandardCharsets.UTF_8)), NOW);
    var receipt = first.complete(upload.uploadId(), NOW);
    Files.write(first.objectPath(receipt.artifactId()), "abcdWXYZ".getBytes(StandardCharsets.UTF_8));

    var reopened = new FileArtifactStore(directory, limits);
    var validation = reopened.validate(java.util.List.of(receipt.artifactId()));

    assertEquals(1, validation.issues().size());
    assertEquals("CORRUPT", validation.issues().getFirst().kind().name());
}

